+      }
+
+      .choice input {
+        width: 1.1rem;
+        height: 1.1rem;
+        margin-top: 0.18rem;
+        accent-color: var(--accent-strong);
+      }
+
+      .choice span {
+        flex: 1;
+      }
+
+      .actions {
+        display: flex;
+        justify-content: flex-end;
+        padding-top: 0.5rem;
+      }
+
+      button {
+        min-width: 9rem;
+        padding: 0.9rem 1.25rem;
+        border: 0;
+        border-radius: 999px;
+        color: #06111f;
+        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
+        font: inherit;
+        font-weight: 800;
+        cursor: pointer;
+        box-shadow: 0 14px 30px rgba(56, 189, 248, 0.28);
+      }
+
