+
+    <script>
+      const quizQuestions = [
+        {
+          id: "language-types",
+          prompt: "Which of these are programming languages?",
+          helpText: "Select every answer that is a real programming language.",
+          choices: ["Python", "HTML", "JavaScript", "Spanish"]
+        },
+        {
