      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: #141b2f;
        --panel-soft: #1a2440;
        --text: #f4f7fb;
        --muted: #b8c3d9;
        --accent: #7dd3fc;
        --accent-strong: #38bdf8;
        --border: #2c3a5c;
        --shadow: 0 24px 70px rgba(0, 0, 0, 0.38);
