          radial-gradient(circle at bottom right, rgba(129, 140, 248, 0.2), transparent 30rem),
          var(--bg);
      }

      main {
        width: min(100% - 2rem, 860px);
        margin: 0 auto;
        padding: 4rem 0;
      }

      .quiz-shell {
        padding: clamp(1.25rem, 3vw, 2rem);
        border: 1px solid rgba(125, 211, 252, 0.18);
        border-radius: 28px;
        background: rgba(20, 27, 47, 0.92);
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
      }

      .eyebrow {
        margin: 0 0 0.5rem;
        color: var(--accent);
        font-size: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.1em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3.5rem);
        line-height: 1.05;
      }

      .intro {
        max-width: 64ch;
        margin: 1rem 0 2rem;
        color: var(--muted);
        font-size: 1.05rem;
      }

      form {
        display: grid;
        gap: 1rem;
      }

      .form-field {
        padding: 1.25rem;
        border: 1px solid var(--border);
        border-radius: 20px;
        background: linear-gradient(145deg, rgba(26, 36, 64, 0.96), rgba(15, 23, 42, 0.96));
      }

      fieldset {
        min-width: 0;
        margin: 0;
        padding: 0;
        border: 0;
      }

      legend {
        margin-bottom: 0.65rem;
        color: var(--text);
        font-size: 1.1rem;
        font-weight: 750;
      }

      .help-text {
        margin: -0.25rem 0 0.95rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .choices {
        display: grid;
        gap: 0.7rem;
      }

      .choice {
        display: flex;
        align-items: flex-start;
        gap: 0.75rem;
        padding: 0.85rem 0.95rem;
        border: 1px solid rgba(184, 195, 217, 0.18);
        border-radius: 14px;
        background: rgba(255, 255, 255, 0.035);
        color: var(--text);
        cursor: pointer;
        transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
      }

      .choice:hover {
        border-color: rgba(125, 211, 252, 0.55);
        background: rgba(125, 211, 252, 0.08);
        transform: translateY(-1px);
      }

      .choice input {
        width: 1.1rem;
        height: 1.1rem;
        margin-top: 0.18rem;
        accent-color: var(--accent-strong);
      }

      .choice span {
        flex: 1;
      }

      .actions {
        display: flex;
        justify-content: flex-end;
        padding-top: 0.5rem;
      }

      button {
        min-width: 9rem;
        padding: 0.9rem 1.25rem;
        border: 0;
        border-radius: 999px;
        color: #06111f;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        box-shadow: 0 14px 30px rgba(56, 189, 248, 0.28);
      }

      button:hover {
        filter: brightness(1.06);
      }

      button:focus-visible,
      input:focus-visible {
        outline: 3px solid #fef08a;
        outline-offset: 3px;
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }
    </style>
  </head>
  <body>
    <main>
      <section class="quiz-shell" data-component="QuizApp" aria-labelledby="quiz-title">
