        <h1 id="quiz-title">Computer Languages</h1>
        <p class="intro">
          Test your knowledge of computer languages. Some questions may have more than one correct answer.
        </p>

        <form>
          <div class="form-field" data-component="Question">
            <fieldset aria-describedby="language-types-help">
              <legend>1. Which of these are programming languages?</legend>
              <p class="help-text" id="language-types-help">
                Select every answer that is a real programming language.
              </p>
              <div class="choices" data-component="ChoiceList">
                <label class="choice" data-component="Choice">
                  <input type="checkbox" name="language-types" value="Python">
                  <span>Python</span>
                </label>
                <label class="choice" data-component="Choice">
                  <input type="checkbox" name="language-types" value="HTML">
                  <span>HTML</span>
                </label>
                <label class="choice" data-component="Choice">
                  <input type="checkbox" name="language-types" value="JavaScript">
                  <span>JavaScript</span>
                </label>
                <label class="choice" data-component="Choice">
                  <input type="checkbox" name="language-types" value="Spanish">
                  <span>Spanish</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="form-field" data-component="Question">
            <fieldset>
              <legend>2. Which languages are commonly compiled before running?</legend>
              <div class="choices" data-component="ChoiceList">
                <label class="choice" data-component="Choice">
                  <input type="checkbox" name="compiled-languages" value="C">
                  <span>C</span>
                </label>
                <label class="choice" data-component="Choice">
                  <input type="checkbox" name="compiled-languages" value="Rust">
                  <span>Rust</span>
                </label>
                <label class="choice" data-component="Choice">
                  <input type="checkbox" name="compiled-languages" value="Swift">
                  <span>Swift</span>
                </label>
                <label class="choice" data-component="Choice">
                  <input type="checkbox" name="compiled-languages" value="CSS">
                  <span>CSS</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="form-field" data-component="Question">
            <fieldset>
              <legend>3. Which languages are commonly used to build websites or web apps?</legend>
              <div class="choices" data-component="ChoiceList">
                <label class="choice" data-component="Choice">
                  <input type="checkbox" name="web-languages" value="JavaScript">
                  <span>JavaScript</span>
                </label>
                <label class="choice" data-component="Choice">
                  <input type="checkbox" name="web-languages" value="TypeScript">
                  <span>TypeScript</span>
                </label>
                <label class="choice" data-component="Choice">
                  <input type="checkbox" name="web-languages" value="PHP">
                  <span>PHP</span>
                </label>
                <label class="choice" data-component="Choice">
                  <input type="checkbox" name="web-languages" value="Fortran">
                  <span>Fortran</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="actions">
            <button type="submit">Submit quiz</button>
          </div>
        </form>
      </section>
    </main>
  </body>
</html>
